'use strict';
const $=s=>document.querySelector(s);
const presets={food:['火鍋','日式料理','義大利麵','韓式烤肉','牛肉麵','隨便吃點'],weekend:['去看電影','咖啡廳放空','戶外走走','在家追劇','來場小旅行','找朋友聚聚'],yesno:['勇敢試試','再想一下','就是現在','換個方向']};
const palette=['#d6b677','#65795e','#b7a783','#3e594a','#b08b60','#879578','#d0c19a','#506958','#a99972','#718362','#c49e6e','#465d48'];
let options=[...presets.food],history=[],rotation=0,spinning=false,sound=false,audioCtx;
try{const saved=JSON.parse(localStorage.getItem('fate-wheel-v1'));if(saved&&Array.isArray(saved.options)&&saved.options.length<=30&&saved.options.every(v=>typeof v==='string'&&v.trim()&&v.length<=32)){options=saved.options;history=Array.isArray(saved.history)?saved.history.filter(h=>h&&typeof h.name==='string'&&Number.isFinite(h.time)).slice(0,20):[];$('#remove-winner').checked=!!saved.remove;}}catch{}
function save(){try{localStorage.setItem('fate-wheel-v1',JSON.stringify({options,history,remove:$('#remove-winner').checked}));}catch{}}
const canvas=$('#wheel'),ctx=canvas.getContext('2d');
function draw(){const n=options.length;ctx.clearRect(0,0,1000,1000);if(!n){ctx.fillStyle='#394735';ctx.beginPath();ctx.arc(500,500,500,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c7cfbc';ctx.font='28px sans-serif';ctx.textAlign='center';ctx.fillText('加入你的第一個選項',500,300);return;}const arc=Math.PI*2/n;for(let i=0;i<n;i++){const a=rotation-Math.PI/2+i*arc;ctx.beginPath();ctx.moveTo(500,500);ctx.arc(500,500,496,a,a+arc);ctx.closePath();ctx.fillStyle=palette[i%palette.length];ctx.fill();ctx.strokeStyle='#f1e2bd30';ctx.lineWidth=2;ctx.stroke();ctx.save();ctx.translate(500,500);ctx.rotate(a+arc/2);ctx.textAlign='right';ctx.textBaseline='middle';ctx.fillStyle=[0,2,4,6,8,10].includes(i%12)?'#2e3728':'#f6efda';ctx.font=`600 ${n>16?21:n>10?26:32}px "Noto Sans TC", sans-serif`;let label=options[i];while(ctx.measureText(label).width>290)label=label.slice(0,-2)+'…';ctx.fillText(label,425,0);ctx.restore();}ctx.beginPath();ctx.arc(500,500,492,0,Math.PI*2);ctx.strokeStyle='#eed9a078';ctx.lineWidth=4;ctx.stroke();}
function render(){const list=$('#options');list.replaceChildren();options.forEach((name,i)=>{const row=document.createElement('div');row.className='option';const dot=document.createElement('span');dot.className='dot';dot.style.background=palette[i%palette.length];const label=document.createElement('span');label.textContent=name;const chance=document.createElement('span');chance.className='chance';chance.textContent=(100/options.length).toFixed(1)+'%';const del=document.createElement('button');del.className='delete';del.textContent='×';del.setAttribute('aria-label','刪除 '+name);del.disabled=spinning;del.onclick=()=>{options.splice(i,1);rotation=0;render();save();};row.append(dot,label,chance,del);list.append(row);});$('#count').textContent=String(options.length).padStart(2,'0');$('#wheel-count').textContent=options.length+' 個可能';$('#spin').disabled=spinning||options.length<2;$('#hub').disabled=spinning||options.length<2;$('#new-option').disabled=spinning;document.querySelectorAll('#add-form button,[data-preset],#clear,#remove-winner').forEach(el=>el.disabled=spinning);$('#hint').textContent=spinning?'命運正在為你尋找答案…':options.length<2?'加入至少 2 個選項，讓命運開始轉動。':'每個選項，都有一樣的機會。';draw();}
function renderHistory(){const el=$('#history');el.replaceChildren();$('#history-count').textContent=history.length;if(!history.length){const p=document.createElement('div');p.className='empty';const icon=document.createElement('span');icon.textContent='◷';p.append(icon,document.createTextNode('尚未轉動，第一個驚喜正在等你。'));el.append(p);return;}history.slice(0,5).forEach((h,i)=>{const r=document.createElement('div');r.className='record';const num=document.createElement('b');num.textContent=String(i+1).padStart(2,'0');const name=document.createElement('span');name.textContent=h.name;const time=document.createElement('time');time.dateTime=new Date(h.time).toISOString();time.textContent=new Date(h.time).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit',hour12:false});r.append(num,name,time);el.append(r);});}
$('#add-form').onsubmit=e=>{e.preventDefault();if(spinning)return;const input=$('#new-option'),value=input.value.trim();if(!value){$('#form-message').textContent='先輸入一個選項吧。';return;}if(options.length>=30){$('#form-message').textContent='最多可放入 30 個選項。';return;}options.push(value);input.value='';$('#form-message').textContent='';rotation=0;render();save();input.focus();};
$('#clear').onclick=()=>{if(spinning)return;options=[];rotation=0;render();save();$('#new-option').focus();};
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{if(spinning)return;options=[...presets[b.dataset.preset]];rotation=0;$('#form-message').textContent='';render();save();});
$('#remove-winner').onchange=save;$('#clear-history').onclick=()=>{history=[];renderHistory();save();};
$('#sound').onclick=()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',String(sound));$('#sound span').textContent=sound?'音效開啟':'音效關閉';if(sound){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume().catch(()=>{});}catch{sound=false;$('#sound').setAttribute('aria-pressed','false');$('#sound span').textContent='音效無法使用';}}};
function tick(freq=650){if(!sound||!audioCtx)return;try{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.connect(gain);gain.connect(audioCtx.destination);osc.frequency.value=freq;gain.gain.setValueAtTime(.045,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.07);osc.start();osc.stop(audioCtx.currentTime+.08);}catch{}}
function randomIndex(n){const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a);}while(a[0]>=limit);return a[0]%n;}
function spin(){if(spinning||options.length<2)return;spinning=true;const n=options.length,index=randomIndex(n),winner=options[index],arc=Math.PI*2/n,start=rotation,tau=Math.PI*2;const desired=-(index+.5)*arc;const delta=((desired-start)%tau+tau)%tau+tau*6;const duration=matchMedia('(prefers-reduced-motion: reduce)').matches?100:4800;render();const began=performance.now();let lastSlice=-1;function animate(now){const t=Math.min(1,(now-began)/duration);rotation=start+delta*(1-Math.pow(1-t,4));draw();const slice=Math.floor(rotation/arc);if(slice!==lastSlice){tick();lastSlice=slice;}if(t<1){requestAnimationFrame(animate);return;}rotation=((rotation%tau)+tau)%tau;spinning=false;history.unshift({name:winner,time:Date.now()});history=history.slice(0,20);$('#winner').textContent=winner;$('#result').showModal();tick(1000);if($('#remove-winner').checked){options.splice(index,1);rotation=0;}render();renderHistory();save();}requestAnimationFrame(animate);}
$('#spin').onclick=spin;$('#hub').onclick=spin;$('#close-result').onclick=()=>$('#result').close();$('#again').onclick=()=>{$('#result').close();spin();};$('#result').addEventListener('close',()=>{$('#spin').focus();});$('#result').addEventListener('click',e=>{if(e.target===$('#result')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});render();renderHistory();document.fonts.ready.then(draw);
